import type { Block } from 'payload'

/**
 * GENERATED by tools/block_config.py from out/bar/schema.json — every defaultValue
 * is injected from out/RdBar.defaults.json, not retyped.
 *
 * The sticky buy bar from the navigation spec, as a content block.
 *
 * A NEW block, and the first in this pipeline that does not come from a page
 * mockup. It exists in the spec as two STATIC FRAMES, one at 1280px and one at
 * 390px, drawn side by side with no stylesheet and no breakpoint between them.
 * tools/bar_from_spec.py slices both out and converts their inline styles to
 * React style objects, so nothing here is retyped either.
 *
 * WHICH PAGES IS THE BLOCK'S OWN PRESENCE. The spec names eight pages for it and
 * seven it must stay off:
 *
 *   "One bar for every marketing page: Home, Your Biology, The Lab, The Protocol,
 *    Our Plans, the ingredient library, the science board, Our standards. Not on
 *    About nb1, FAQ, Contact, Log in, the legal pages, the order funnel, or the
 *    Core PDP, which keeps its own buy bar."
 *
 * Adding the block is the opt-in, so that list needs no code, and a page that
 * gets renamed cannot fall out of step with a hardcoded one.
 *
 * WHEN IT SHOWS IS THE BLOCK'S OWN POSITION. The spec gives two anchors:
 *
 *   Appears  "When the first section has fully scrolled out of view."
 *   Hides    "When the final CTA section or the footer enters view, so there is
 *             only one buy button on screen."
 *
 * Neither is nameable from inside a block — both are facts about the page.
 *
 * The first is found automatically: the first element inside the page's first
 * block, which is the hero on all eight pages. NOT the first block itself — Our
 * Standards, the ingredient library, the science board and Your Biology are ONE
 * block each, so "the first block" there is the whole page and the bar would
 * never appear.
 *
 * The second is THIS BLOCK'S OWN SPOT: the component drops a zero-height marker
 * where the block sits and hides the bar when that marker comes into view. Put
 * the block immediately before the final CTA and the rule is the spec's; put it
 * last and the bar clears the footer instead — which is the spec's own second
 * option, and the only one available on a one-block page, where there is no
 * boundary to stand between.
 *
 * The alternative was two selector fields per page — two more things to leave
 * blank or let go stale, with nothing to catch it when they do. Here the rule is
 * the position in the admin's own block list: visible, and impossible to point at
 * nothing.
 *
 * THE DEFAULTS CARRY CURRENCY TOKENS, WHICH IS A DEPARTURE. Every other block's
 * defaultValue is the mockup's own value and the tokens are applied when the page
 * is SEEDED (see claude/currency-tokens-in-seeds.md). This block has no seed —
 * it is placed by hand, per page — so its defaults are the content a visitor is
 * served. Shipping the spec's literal "£463" and "£99" would put hardcoded pounds
 * on every bar anyone adds, and there would be no later pass to fix them.
 *
 * `{{price:core:1}}` rather than `{{99}}` for the same reason it matters: Core is
 * 99 EUR/GBP/CHF but 419 AED, so a flat conversion would quote an AED visitor a
 * twentieth of the real price. {{463}} is a flat claim and stays flat — the same
 * token the checkout seed already uses for it.
 *
 * ONE THING THE SPEC DRAWS THAT THIS QUESTIONS, and recreates anyway: "From £99"
 * sits next to the HIGHEST of the three Core terms (99 / 94 / 89 for 1 / 4 / 12
 * months). "From" usually means the lowest. Left as drawn.
 *
 * NO ANCHOR ID. Every other block has one so an editor can link to the section.
 * A bar fixed to the bottom of the window is not a place on the page, so a
 * fragment pointing at it would do nothing, and a field that does nothing is a
 * field someone will fill in.
 */
export const RdBarBlock: Block = {
  slug: "rdBar",
  interfaceName: "RdBarBlock",
  labels: { singular: "Sticky buy bar", plural: "Sticky buy bar" },
  fields: [
    { name: "productName", type: "text", localized: true, required: true, label: "Product name", admin: { description: "The first line on desktop. Hidden on phones, where there is no room for it \u2014 the bar shows the price and the short note instead." }, defaultValue: "Gut test and daily formula" },
    { name: "note", type: "text", localized: true, label: "Desktop note", admin: { description: "The dotted line beside the product name, desktop only. {{463}} is a currency token: it resolves to the right amount in the visitor's currency and re-resolves when they switch. Type a bare number inside braces for a flat amount, or leave the token alone." }, defaultValue: "Analysis worth {{463}} included" },
    { name: "price", type: "text", localized: true, label: "Price", admin: { description: "Shown on both layouts. {{price:core:1}} is a LIVE price \u2014 the Core one-month rate for the visitor's currency, from the subscriptions API. A plain {{99}} would show an AED visitor 99 where the real figure is 419, so leave it as a price token unless the bar is meant to carry a flat claim." }, defaultValue: "From {{price:core:1}}" },
    { name: "priceSuffix", type: "text", localized: true, label: "Price suffix", admin: { description: "Set in the body face beside the price, smaller. The leading space is deliberate \u2014 it is the gap between the amount and the unit." }, defaultValue: " / mo" },
    { name: "mobileNote", type: "text", localized: true, label: "Phone note", admin: { description: "Sits under the price on phones, in place of the product name and the longer desktop note. Short: it has to stay on one line next to the button." }, defaultValue: "Analysis included" },
    { name: "ctaLabel", type: "text", localized: true, required: true, label: "Button", admin: { description: "The lime pill, on both layouts. The arrow after it is drawn by the component and is not part of this text." }, defaultValue: "Order your kit" },
    { name: "ctaHref", type: "text", localized: true, label: "Button destination", admin: { description: "A slug \u2014 the locale is added when the page renders, so one value is right in all nine. The spec points this at the order funnel. A full url, a /path, a #anchor, mailto: or tel: is passed through as typed." }, defaultValue: "order-v2" },
  ],
}
